"""Async checkbox interaction for evaluation widget execution."""

from __future__ import annotations

from typing import cast

from playwright.async_api import Error, Frame, Locator, Page

from src.field import FieldDescriptor
from src.key_catalog import (
    PK_LABEL,
    PK_VALUE,
    WK_CHECKBOX,
)
from src.types.typed import JsonObject, JsonValue, as_json_object
from src.widget.base import build_match_variants

from ._choice_text import ellipsized_prefix, normalized_choice_text
from ._choice_widgets import choice_descendants
from ._normalization import parse_checkbox_expected
from ._widget_dom import evaluate_true


async def _checkbox_target(locator: Locator) -> Locator:
    choices = await choice_descendants(locator, WK_CHECKBOX)
    if choices is None:
        return locator
    return choices.first


async def _checkbox_choice_payload(candidate: Locator) -> JsonObject:
    payload = as_json_object(
        cast(
            object,
            await candidate.evaluate(
                """
                (el) => {
                    const ownLabel = el.labels && el.labels.length ? el.labels[0] : null;
                    const parentLabel = el.closest("label");
                    const label = el.getAttribute("aria-label")
                        || (ownLabel && ownLabel.textContent)
                        || (parentLabel && parentLabel.textContent)
                        || el.value
                        || "";
                    return {
                        value: String(el.value || ""),
                        label: String(label).trim()
                    };
                }
                """
            ),
        )
    )
    return payload


async def _checkbox_choice_matches(
    candidate: Locator,
    normalized_variants: set[str],
) -> bool:
    payload = await _checkbox_choice_payload(candidate)
    return any(
        normalized_choice_text(payload.get(key)) in normalized_variants
        for key in (PK_VALUE, PK_LABEL)
    )


async def _checkbox_choice_prefix_matches(
    candidate: Locator,
    prefixes: set[str],
) -> bool:
    payload = await _checkbox_choice_payload(candidate)
    return any(
        any(
            normalized_choice_text(payload.get(key)).startswith(prefix)
            for prefix in prefixes
        )
        for key in (PK_VALUE, PK_LABEL)
    )


async def _checkbox_group_choice_target(
    page: Page | Frame,
    field: FieldDescriptor,
    expected: JsonValue,
) -> Locator | None:
    if not field.name_attr:
        return None
    target_variants = build_match_variants(expected)
    normalized_variants = {
        normalized_choice_text(variant) for variant in target_variants
    }
    ellipsized_prefixes = {
        prefix
        for variant in target_variants
        if (prefix := ellipsized_prefix(variant)) is not None
    }
    checkboxes = page.locator(f'input[type="{WK_CHECKBOX}"][name="{field.name_attr}"]')
    for index in range(await checkboxes.count()):
        candidate = checkboxes.nth(index)
        if await _checkbox_choice_matches(candidate, normalized_variants):
            return candidate
    if not ellipsized_prefixes:
        return None
    prefix_matches: list[Locator] = []
    for index in range(await checkboxes.count()):
        candidate = checkboxes.nth(index)
        if await _checkbox_choice_prefix_matches(candidate, ellipsized_prefixes):
            prefix_matches.append(candidate)
    if len(prefix_matches) == 1:
        return prefix_matches[0]
    return None


async def _checked_state(locator: Locator) -> bool:
    try:
        return await locator.is_checked()
    except (RuntimeError, TimeoutError, Error):
        raw = cast(
            object,
            await locator.evaluate(
                """
                (el) => {
                    if (typeof el.checked === "boolean") return el.checked;
                    const stateNode = el.closest('[aria-checked], [role="checkbox"], [role="radio"]');
                    const aria = stateNode ? stateNode.getAttribute("aria-checked") : el.getAttribute("aria-checked");
                    return aria === "true";
                }
                """
            ),
        )
    return raw is True


async def _click_associated_control(
    locator: Locator,
    should_check: bool,
) -> None:
    if await evaluate_true(
        locator,
        """
        (el, shouldCheck) => {
            const label = el.labels && el.labels.length ? el.labels[0] : el.closest("label");
            const control = label || el.closest('[role="checkbox"], [role="radio"], [aria-checked]');
            if (control) {
                control.click();
                return true;
            }
            const option = el.parentElement?.querySelector(
                `button[data-option="${shouldCheck ? "yes" : "no"}"]`
            );
            if (!option) return false;
            option.click();
            return true;
        }
        """,
        should_check,
    ):
        return
    raise ValueError("Unable to locate visible control for hidden checkbox/radio input")


async def _set_checked_state(locator: Locator, should_check: bool) -> None:
    if not await evaluate_true(
        locator,
        """
        (el, shouldCheck) => {
            if (!("checked" in el)) return false;
            if (el.checked === shouldCheck) return true;
            el.checked = shouldCheck;
            el.dispatchEvent(new Event("input", { bubbles: true }));
            el.dispatchEvent(new Event("change", { bubbles: true }));
            return el.checked === shouldCheck;
        }
        """,
        should_check,
    ):
        raise ValueError("Unable to update checkbox/radio checked state")


async def _try_native_checked_action(locator: Locator, should_check: bool) -> bool:
    try:
        visible = await locator.is_visible()
    except (RuntimeError, TimeoutError, Error):
        visible = False
    if not visible:
        return False
    try:
        if should_check:
            await locator.check()
        else:
            await locator.uncheck()
        return True
    except (TimeoutError, Error):
        return False


async def _try_label_checked_action(locator: Locator, should_check: bool) -> bool:
    try:
        await _click_associated_control(locator, should_check)
        return True
    except (ValueError, RuntimeError, TimeoutError, Error):
        return False


async def _set_checked_async(locator: Locator, should_check: bool) -> None:
    """Set checkbox/radio state, falling back to labels for hidden custom controls."""
    if await _checked_state(locator) == should_check:
        return

    if await _try_native_checked_action(locator, should_check):
        return

    await _try_label_checked_action(locator, should_check)

    if await _checked_state(locator) != should_check:
        await _set_checked_state(locator, should_check)

    if await _checked_state(locator) != should_check:
        raise ValueError("Unable to update checkbox/radio state")


async def set_checkbox_async(
    page: Page | Frame,
    field: FieldDescriptor,
    locator: Locator,
    value: JsonValue,
) -> None:
    """Set a native checkbox or a named checkbox group's selected options."""
    parsed = parse_checkbox_expected(value)
    if parsed is not None:
        await _set_checked_async(await _checkbox_target(locator), parsed)
        return
    if isinstance(value, list):
        for choice in value:
            target = await _checkbox_group_choice_target(page, field, choice)
            if target is None:
                raise ValueError(f"Unable to match checkbox option for {choice!r}")
            await _set_checked_async(target, True)
        return
    target = await _checkbox_group_choice_target(page, field, value)
    if target is None:
        raise ValueError(f"Unable to match checkbox option for {value!r}")
    await _set_checked_async(target, True)

